222	/// Writes a lazy CSS `calc(<calc-sum>) expression`.
223	/// If only a single operand is written, `calc(<calc-sum>)` is omitted.
224	struct CalcWriter<'a, 'b> {
225	    w: &'b mut CssWriter<'a>,
226	    /// The byte-index in the [`CssWriter::buf`].
227	    start_idx: usize,
228	    count: usize,
229	}
230	
231	impl<'a, 'b> CalcWriter<'a, 'b> {
232	    fn start(w: &'b mut CssWriter<'a>) -> Self {
233	        let start_idx = w.buf.len();
234	        Self { w, start_idx, count: 0 }
235	    }
236	
237	    /// Add a value.
238	    ///
239	    /// - If it is zero, it will be omitted.
240	    /// - If it is negative, it will be negated and subtracted. This makes the
241	    ///   assumption that the formatted string `"+ {val}"` is equivalent to
242	    ///   `"- {val.neg()}"`.
243	    ///   This would for example not be the case if a value somehow implements
244	    ///   [`Ord`] and would be formatted as a non-parenthesized binary operator
245	    ///   with the same or lower precedence, e.g.
246	    ///   `"+ -1pt + 2em"` != `"- 1pt - 2em"`.
247	    fn sum<T>(&mut self, value: T) -> &mut Self
248	    where
249	        T: ToCss + Numeric + Ord,
250	    {
251	        if value == T::zero() {
252	            return self;
253	        }
254	
255	        if self.count == 0 {
256	            self.w.emit(value);
257	        } else {
258	            // Negate the value and subtract it, in case it is negative.
259	            if value < T::zero() {
260	                self.w.write(" - ");
261	                self.w.emit(value.neg());
262	            } else {
263	                self.w.write(" + ");
264	                self.w.emit(value);
265	            }
266	        }
267	        self.count += 1;
268	        self
269	    }
270	}
271	
272	impl Drop for CalcWriter<'_, '_> {
273	    fn drop(&mut self) {
274	        match self.count {
275	            0 => {
276	                // An empty `calc()` function call is invalid, so write a `0`,
277	                // which is also valid for lengths.
278	                self.w.write("0");
279	            }
280	            1 => (),
281	            2.. => {
282	                // TODO: Use insert_str once merged:
283	                // https://github.com/typst/ecow/pull/59
284	                let mut buf = EcoString::with_capacity(self.w.buf.len() + 6);
285	
286	                // NOTE: This assumes the `ToCss` implementation of all values
287	                // should only modify text that itself has written into the
288	                // buffer, which seems reasonable.
289	                buf.push_str(&self.w.buf[..self.start_idx]);
290	                buf.push_str("calc(");
291	                buf.push_str(&self.w.buf[self.start_idx..]);
292	                buf.push_str(")");
293	
294	                self.w.buf = buf;
295	            }
296	        }
297	    }
298	}
