487	/// Adds an alpha component argument to a CSS call if the alpha value is not 1.
488	trait MaybeAlpha {
489	    fn maybe_alpha_arg(&mut self, value: f32);
490	}
491	
492	impl MaybeAlpha for CallWriter<'_, '_> {
493	    fn maybe_alpha_arg(&mut self, value: f32) {
494	        if !is_very_close(value, 1.0) {
495	            self.arg_with(to_ratio(value), Separator::Slash);
496	        }
497	    }
498	}
499	
500	/// Convert a raw degree value into an `Angle`.
501	fn to_angle(degrees: impl Into<f64>) -> Angle {
502	    Angle::deg(degrees.into())
503	}
504	
505	/// Convert a raw value between 0 and 1 to a `Ratio`.
506	fn to_ratio(v: impl Into<f64>) -> Ratio {
507	    Ratio::new(v.into())
508	}
509	
510	/// Whether two component values are close enough that there is no
511	/// difference when encoding them with 12-bit. 12 bit is the highest
512	/// reasonable color bit depth found in the industry.
513	fn is_very_close(a: impl Into<f64>, b: impl Into<f64>) -> bool {
514	    const MAX_BIT_DEPTH: u32 = 12;
515	    const EPS: f64 = 0.5 / 2_i32.pow(MAX_BIT_DEPTH) as f64;
516	    (a.into() - b.into()).abs() < EPS
517	}
